kuru.linux:
h={hedef}
[ -d "$h" ] && h="$h/"{dosya}
if [ -f "$h" ]; then echo durum=degisecek; echo "mevcut_ozet=$(sha256sum "$h" | cut -d' ' -f1)";
else echo durum=yeni_dosya; fi
echo yeni_ozet={_ozet}

geri_al.linux:
h={hedef}
[ -d "$h" ] && h="$h/"{dosya}
